def count_passing_ways(n, m):
    # Initialize a 2D list to store the dynamic programming states
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: passing 0 times
    for i in range(n + 1):
        dp[0][i] = 1

    # Fill the dynamic programming table
    for t in range(1, m + 1):
        for i in range(1, n + 1):
            dp[t][i] = dp[t - 1][i - 1] + dp[t - 1][i]

    # Return the result
    return dp[m][n]

